import{_ as l,a0 as o,w as p,s as r,ao as u,I as a,x as t,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"基础：在 Linux 终端中移动文件 | LCTT x X-CMD","titleTemplate":false,"description":"基础：在 Linux 终端中移动文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基础：在 Linux 终端中移动文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基础：在 Linux 终端中移动文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210804 Move files in the Linux terminal","title":"基础：在 Linux 终端中移动文件","tag":"202108","desc":""},"relativePath":"202108/20210804 Move files in the Linux terminal.md","filePath":"[post].md"}'),d={name:"202108/20210804 Move files in the Linux terminal.md"};function m(x,e,f,g,h,k){const s=o("Link");return p(),r("div",null,[e[15]||(e[15]=u(`<h1 id="基础-在-linux-终端中移动文件" tabindex="-1">基础：在 Linux 终端中移动文件 <a class="header-anchor" href="#基础-在-linux-终端中移动文件" aria-label="Permalink to “基础：在 Linux 终端中移动文件”">​</a></h1><blockquote><p>使用 mv 命令将一个文件从一个位置移动到另一个位置。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/13/112248lnal8a0qz50zqzld.jpg" alt=""></p><p>要在有图形界面的计算机上移动一个文件，你要打开该文件当前所在的文件夹，然后打开另一个窗口导航到你想把文件移到的文件夹。最后，你把文件从一个窗口拖到另一个窗口。</p><p>要在终端中移动文件，你可以使用 <code>mv</code> 命令将文件从一个位置移动到另一个位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv example.txt ~/Documents</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls ~/Documents</span></span>
<span class="line"><span>example.txt</span></span></code></pre></div><p>在这个例子中，你已经把 <code>example.txt</code> 从当前文件夹移到了主目录下的 <code>Documents</code> 文件夹中。</p><p>只要你知道一个文件在 <em>哪里</em>，又想把它移到 <em>哪里</em> 去，你就可以把文件从任何地方移动到任何地方，而不管你在哪里。与在一系列窗口中浏览你电脑上的所有文件夹以找到一个文件，然后打开一个新窗口到你想让该文件去的地方，再拖动该文件相比，这可以大大节省时间。</p><p>默认情况下，<code>mv</code> 命令完全按照它被告知的那样做：它将一个文件从一个位置移动到另一个位置。如果在目标位置已经存在一个同名的文件，它将被覆盖。为了防止文件在没有警告的情况下被覆盖，请使用 <code>--interactive</code>（或简写 <code>-i</code>）选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv -i example.txt ~/Documents</span></span>
<span class="line"><span>mv: overwrite &#39;/home/tux/Documents/example.txt&#39;?</span></span></code></pre></div><hr>`,11)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),n(s,{href:"https://opensource.com/article/21/8/move-files-linux"},{default:i(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/21/8/move-files-linux",-1)])]),_:1})]),a("p",null,[e[6]||(e[6]=t("作者：",-1)),n(s,{href:"https://opensource.com/users/seth"},{default:i(()=>[...e[2]||(e[2]=[t("Seth Kenlon",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const c=l(d,[["render",m]]);export{v as __pageData,c as default};
